{
  case TarFormat.V7:
    // do something if v7
    break;
  case TarFormat.Ustar:
    // do something if ustar
    break;
  case TarFormat.Pax:
    // do something if pax
    break;
  case TarFormat.Gnu:
    // do something if gnu
    break;
}
